class MyClass:
    count = 0

    @classmethod
    def increment(cls):
        cls.count += 1

    @staticmethod
    def add(a, b):
        return a + b

MyClass.increment()
print(MyClass.count)      # 1
print(MyClass.add(2, 3))  # 5

